#	system.perspective.print('onEditCellCommit() called with %s'%event)
	userId = self.view.custom.security.userId

	record = self.props.data[event['row']]
	roleId = record['roleId']
	roleUserSource = record['userSource']
	roleData = dict(system.kanoa.utilities.convertDatasetToJSON(system.kanoa.security.getRoles({'roleId': roleId}))[0])

	if event.column == 'roleName':
		if roleData['userSource'] is None:
			roleData['roleName'] = event.value
#			system.perspective.print("updateRole() called with %s"%roleData)
			retVal, msg = system.kanoa.security.updateRole(roleData, userId)
		else:
			msg = "Cannot edit the name of a role that exists in a user source"
	elif event.column == 'enabled':
		roleData['enabled'] = event.value
		retVal, msg = system.kanoa.security.updateRole(roleData, userId)
	else:
		functionId = system.kanoa.utilities.getFieldValue('functionId', system.kanoa.security.getUserFunctions({'label': event.column}))
		retVal, msg = system.kanoa.security.updateRoleFunctions({'roleId': roleId, 'functionId': functionId, 'enabled': event.value}, userId)

	if msg: system.perspective.sendMessage('showWarningToast', {'message': "Could not update role function: %s"%msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': "Role Function successfully updated"})

	self.view.refreshBinding("custom.roles.data")

	return

