customMethods.script:

userId = self.view.custom.security.userId
selectedRole = dict(self.view.custom.roles.selectedData[0])
if selectedRole['userSource'] == 'Kanoa Internal':
	retVal, msg = system.kanoa.security.deleteRole(selectedRole['roleId'], userId)
	if msg: system.perspective.sendMessage('showWarningToast', {'message': "Could not delete role: %s"%msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': "Role successfully deleted"})
else:
	selectedRole['enabled'] = False
	retVal, msg = system.kanoa.security.updateRole(selectedRole, userId)
	if msg: system.perspective.sendMessage('showWarningToast', {'message': "Could not disable role: %s"%msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': "Role associated with userSource '%s' now disabled."%selectedRole['userSource']})

self.view.refreshBinding("custom.roles.data")

return

